WITH selected_titles AS MATERIALIZED (SELECT t.id FROM title t WHERE t.production_year>1936),
mk_counts AS MATERIALIZED (SELECT mk.movie_id, COUNT(*)::HUGEINT AS n FROM movie_keyword mk JOIN selected_titles eligible ON eligible.id=mk.movie_id WHERE TRUE GROUP BY mk.movie_id)
SELECT COALESCE(SUM(mk.n),0) FROM selected_titles t JOIN mk_counts mk ON mk.movie_id=t.id;

